-- M17.5 PRE-A4 M2: exact A2 score-first capacity successor. No data writes.
-- Frozen D1/D1b: eligibility -> score -> all-score invariant -> top-N -> hydrate.
BEGIN;
SET LOCAL search_path=pg_catalog,pg_temp;
DO $m2$
DECLARE v_ext name; v_oid oid; v_hash text; v_before jsonb; v_definition text;
BEGIN
 SELECT n.nspname INTO STRICT v_ext FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace WHERE e.extname='vector';
 v_oid:=to_regprocedure(format('gov_repo.technical_semantic_context_search_v1(uuid,uuid,bigint,bigint,timestamptz,text,text,%I.vector,text,text,text,integer,text,text,integer,double precision)',v_ext));
 IF v_oid IS NULL OR (SELECT count(*) FROM pg_proc WHERE pronamespace='gov_repo'::regnamespace AND proname='technical_semantic_context_search_v1')<>1 THEN
  RAISE EXCEPTION 'TECHNICAL_M2_EXACT_IDENTITY_REQUIRED' USING ERRCODE='55000'; END IF;
 SELECT to_jsonb(p)-'prosrc',encode(sha256(convert_to(replace(replace(p.prosrc,chr(13),''),quote_ident(v_ext)||'.','__vector__.'),'UTF8')),'hex')
 INTO v_before,v_hash FROM pg_proc p WHERE p.oid=v_oid;
 IF (SELECT pg_get_userbyid(proowner)<>'postgres' OR NOT prosecdef OR provolatile<>'v' OR proparallel<>'u'
   OR prorettype<>'jsonb'::regtype OR proconfig IS DISTINCT FROM ARRAY['search_path=pg_catalog, pg_temp','lock_timeout=5s']
   FROM pg_proc WHERE oid=v_oid)
   OR EXISTS(SELECT FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a
    WHERE p.oid=v_oid AND (a.privilege_type<>'EXECUTE' OR a.is_grantable OR a.grantee NOT IN ('postgres'::regrole,'service_role'::regrole)))
   OR NOT has_function_privilege('service_role',v_oid,'EXECUTE')
   OR has_function_privilege('anon',v_oid,'EXECUTE') OR has_function_privilege('authenticated',v_oid,'EXECUTE')
   OR EXISTS(SELECT FROM unnest(ARRAY['anon','authenticated','service_role']) r WHERE has_schema_privilege(r,v_ext,'CREATE')) THEN
  RAISE EXCEPTION 'TECHNICAL_M2_STARTING_CAPABILITY_DRIFT' USING ERRCODE='55000'; END IF;
 IF v_hash NOT IN ('8077fddbb72882061211ba767716d5e1d565b4109156b1b6c17651e1f53c568c','e9f89eb27c33e7c5b03d73142432c3fb3097e78343aedad4c702e24097a11271') THEN RAISE EXCEPTION 'TECHNICAL_M2_STARTING_BODY_DRIFT' USING ERRCODE='55000'; END IF;
 IF v_hash='e9f89eb27c33e7c5b03d73142432c3fb3097e78343aedad4c702e24097a11271' THEN RETURN; END IF;
 v_definition:=replace($definition$CREATE OR REPLACE FUNCTION gov_repo.technical_semantic_context_search_v1(
 p_verified_organisation_id uuid,p_verified_actor_user_id uuid,p_verified_session_iat bigint,p_verified_session_exp bigint,p_verified_credential_epoch timestamptz,
 p_repository_id text,p_snapshot_id text,p_query __vector__.vector,p_provider text,p_model text,p_version text,p_dimension integer,p_schema text,p_query_recipe text,p_limit integer,p_threshold double precision)
 RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER VOLATILE PARALLEL UNSAFE CALLED ON NULL INPUT
 SET search_path=pg_catalog,pg_temp SET lock_timeout='5s' AS $technical$
DECLARE v_org uuid; v_space jsonb; v_result jsonb; v_root_allowed boolean;
 v_query_unit __vector__.vector; v_numeric_invalid boolean;
BEGIN
 SELECT u.organisation_id INTO v_org FROM gov_repo.governance_users u WHERE u.user_id=p_verified_actor_user_id;
 IF v_org IS NULL OR v_org IS DISTINCT FROM p_verified_organisation_id THEN RAISE EXCEPTION 'TECHNICAL_ACCESS_DENIED' USING ERRCODE='GV003'; END IF;
 PERFORM 1 FROM gov_repo.l14_session_basis_v1(v_org,p_verified_actor_user_id,p_verified_session_iat,p_verified_session_exp,p_verified_credential_epoch);
 IF NOT FOUND THEN RAISE EXCEPTION 'TECHNICAL_ACCESS_DENIED' USING ERRCODE='GV003'; END IF;
 IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 20 OR p_threshold IS NULL OR p_threshold NOT BETWEEN -1 AND 1 THEN
  RAISE EXCEPTION 'INVALID_TECHNICAL_OPTIONS' USING ERRCODE='22023'; END IF;
 IF p_query_recipe IS DISTINCT FROM 'TECHNICAL_CONTEXT_QUERY_V1' OR p_query IS NULL OR p_dimension IS NULL OR p_dimension NOT BETWEEN 1 AND 16000
  OR __vector__.vector_dims(p_query)<>p_dimension OR __vector__.vector_norm(p_query)<=0
  OR EXISTS(SELECT FROM unnest(ARRAY[p_schema,p_provider,p_model,p_version]) v WHERE v IS NULL OR NOT(v ~ '[^[:space:]]') OR octet_length(v)>512 OR lower(btrim(v)) IN ('latest','default','unknown')) THEN
  RAISE EXCEPTION 'INVALID_TECHNICAL_QUERY' USING ERRCODE='22023'; END IF;
 -- Numeric safety amendment: admit all finite nonzero float32 vectors, normalize once here.
 v_query_unit := __vector__.l2_normalize(p_query);
 IF (p_repository_id IS NOT NULL AND p_repository_id<>'' AND p_repository_id !~ '^[0-9a-f]{64}$')
  OR (p_snapshot_id IS NOT NULL AND p_snapshot_id<>'' AND p_snapshot_id !~ '^[0-9a-f]{64}$') THEN
  RAISE EXCEPTION 'INVALID_TECHNICAL_SCOPE' USING ERRCODE='22023'; END IF;
 v_space:=jsonb_build_object('projection_schema_version',p_schema,'provider_id',p_provider,'model_id',p_model,'model_version',p_version,'dimension',p_dimension);
 IF current_setting('statement_timeout')::interval<=interval '0' OR current_setting('statement_timeout')::interval>interval '5 seconds'
  OR p_repository_id IS NULL OR p_repository_id='' OR p_snapshot_id IS NULL OR p_snapshot_id='' THEN
  RETURN jsonb_build_object('contract_version','GOVIA_SR2_TECHNICAL_CONTEXT_READ_V1','observed_at',CASE WHEN isfinite(clock_timestamp()) THEN to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') ELSE NULL END,'embedding_space',v_space,'scope',NULL,
   'algorithm','EXACT_COSINE_V1','selection_policy','EXACT_SNAPSHOT_LATEST_PROJECTION_IN_SPACE_V1','authorization_semantics','AUTHORIZATION_AS_OF_HYDRATION_SNAPSHOT',
   'coverage','BOUNDED_RECORDED_REPRESENTATIONS_AT_EXACT_SNAPSHOT','status','SEMANTIC_CONTEXT_UNAVAILABLE','reason',
    CASE WHEN current_setting('statement_timeout')::interval<=interval '0' OR current_setting('statement_timeout')::interval>interval '5 seconds' THEN 'EXECUTION_BUDGET_REQUIRED' ELSE 'SCOPE_REQUIRED' END,'hits','[]'::jsonb);
 END IF;
 WITH acquired_clock AS MATERIALIZED (SELECT clock_timestamp() AS at),
 root AS MATERIALIZED (SELECT rt.* FROM gov_repo.sr2_repositories_v1 rt
  JOIN gov_repo.technical_source_connections cn ON cn.organisation_id=v_org AND cn.organisation_id=rt.organisation_id AND cn.connection_id=rt.connection_id
   AND cn.family='REPOSITORY' AND cn.source_system_id=rt.source_system_id AND cn.provider_code=rt.provider_code
  WHERE rt.organisation_id=v_org AND rt.repository_id=p_repository_id COLLATE "C" AND (rt.organisation_id IS NOT NULL AND rt.repository_id IS NOT NULL AND rt.connection_id IS NOT NULL AND rt.source_system_id IS NOT NULL AND rt.provider_code IS NOT NULL AND rt.provider_instance_id IS NOT NULL AND rt.provider_repository_id IS NOT NULL AND rt.display_label IS NOT NULL AND rt.verification_method IS NOT NULL AND rt.verifier_version IS NOT NULL AND rt.verified_at IS NOT NULL AND rt.recorded_at IS NOT NULL AND ((octet_length(rt.connection_id) BETWEEN 1 AND 512 AND rt.connection_id ~ '[^[:space:]]' AND octet_length(rt.source_system_id) BETWEEN 1 AND 512 AND rt.source_system_id ~ '[^[:space:]]' AND octet_length(rt.provider_code) BETWEEN 1 AND 512 AND rt.provider_code ~ '[^[:space:]]' AND octet_length(rt.provider_instance_id) BETWEEN 1 AND 512 AND rt.provider_instance_id ~ '[^[:space:]]' AND octet_length(rt.provider_repository_id) BETWEEN 1 AND 512 AND rt.provider_repository_id ~ '[^[:space:]]' AND octet_length(rt.display_label) BETWEEN 1 AND 512 AND rt.display_label ~ '[^[:space:]]' AND octet_length(rt.verification_method) BETWEEN 1 AND 512 AND rt.verification_method ~ '[^[:space:]]' AND octet_length(rt.verifier_version) BETWEEN 1 AND 512 AND rt.verifier_version ~ '[^[:space:]]') IS TRUE) AND ((rt.repository_id=pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(gov_repo.frame_identity(ARRAY['GOVIA_SR2_ROOT_V1',rt.organisation_id::text,rt.connection_id::text,rt.source_system_id::text,rt.provider_code::text,rt.provider_instance_id::text,rt.provider_repository_id::text]::text[]), 'UTF8')), 'hex')) IS TRUE) AND ((rt.verification_method='PROVIDER_REPOSITORY_ID_VERIFIED_V1' AND isfinite(rt.verified_at) AND isfinite(rt.recorded_at) AND rt.verified_at<=rt.recorded_at) IS TRUE)) AND rt.verified_at BETWEEN '0001-01-01 UTC'::timestamptz AND (SELECT at FROM acquired_clock) AND rt.recorded_at BETWEEN '0001-01-01 UTC'::timestamptz AND (SELECT at FROM acquired_clock)),
 snapshot AS MATERIALIZED (SELECT sn.* FROM gov_repo.sr2_snapshots_v1 sn WHERE sn.organisation_id=v_org AND sn.repository_id=p_repository_id COLLATE "C" AND sn.snapshot_id=p_snapshot_id COLLATE "C" AND EXISTS(SELECT FROM root)),
 compatible AS MATERIALIZED (SELECT r.*,((r.organisation_id IS NOT NULL AND r.repository_id IS NOT NULL AND r.snapshot_id IS NOT NULL AND r.subject_id IS NOT NULL AND r.projection_id IS NOT NULL AND r.representation_id IS NOT NULL AND r.projection_schema_version IS NOT NULL AND r.projection_fingerprint IS NOT NULL AND r.content_class IS NOT NULL AND r.projection_admitted_at IS NOT NULL AND r.provider_id IS NOT NULL AND r.model_id IS NOT NULL AND r.model_version IS NOT NULL AND r.dimension IS NOT NULL AND r.embedding IS NOT NULL AND r.capture_id IS NOT NULL AND r.capture_observed_at IS NOT NULL AND r.generated_at IS NOT NULL AND r.indexed_at IS NOT NULL AND r.recorded_at IS NOT NULL AND ((r.dimension BETWEEN 1 AND 16000) IS TRUE) AND ((__vector__.vector_dims(r.embedding)=r.dimension) IS TRUE) AND ((__vector__.vector_norm(r.embedding)>0 AND __vector__.vector_norm(r.embedding) NOT IN ('NaN'::float8,'Infinity'::float8)) IS TRUE) AND (((octet_length(r.projection_schema_version) BETWEEN 1 AND 512 AND r.projection_schema_version ~ '[^[:space:]]' AND lower(btrim(r.projection_schema_version)) NOT IN ('latest','default','unknown')) AND (octet_length(r.provider_id) BETWEEN 1 AND 512 AND r.provider_id ~ '[^[:space:]]' AND lower(btrim(r.provider_id)) NOT IN ('latest','default','unknown')) AND (octet_length(r.model_id) BETWEEN 1 AND 512 AND r.model_id ~ '[^[:space:]]' AND lower(btrim(r.model_id)) NOT IN ('latest','default','unknown')) AND (octet_length(r.model_version) BETWEEN 1 AND 512 AND r.model_version ~ '[^[:space:]]' AND lower(btrim(r.model_version)) NOT IN ('latest','default','unknown')) AND r.content_class='PROTECTED_CONTEXT_V1') IS TRUE) AND ((isfinite(r.capture_observed_at) AND isfinite(r.projection_admitted_at) AND isfinite(r.generated_at) AND isfinite(r.indexed_at) AND isfinite(r.recorded_at) AND greatest(r.capture_observed_at,r.projection_admitted_at)<=r.generated_at AND r.generated_at<=r.indexed_at AND r.indexed_at<=r.recorded_at) IS TRUE) AND ((r.representation_id=pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(gov_repo.frame_identity(ARRAY['GOVIA_SR2_REPRESENTATION_V1',r.organisation_id::text,r.repository_id::text,r.snapshot_id::text,r.subject_id::text,r.projection_id::text,r.projection_schema_version::text,r.projection_fingerprint::text,r.provider_id::text,r.model_id::text,r.model_version::text,r.dimension::text]::text[]), 'UTF8')), 'hex')) IS TRUE)) AND r.projection_admitted_at BETWEEN '0001-01-01 UTC'::timestamptz AND (SELECT at FROM acquired_clock) AND r.capture_observed_at BETWEEN '0001-01-01 UTC'::timestamptz AND (SELECT at FROM acquired_clock) AND r.generated_at BETWEEN '0001-01-01 UTC'::timestamptz AND (SELECT at FROM acquired_clock) AND r.indexed_at BETWEEN '0001-01-01 UTC'::timestamptz AND (SELECT at FROM acquired_clock) AND r.recorded_at BETWEEN '0001-01-01 UTC'::timestamptz AND (SELECT at FROM acquired_clock)) IS TRUE AS valid_rep
  FROM gov_repo.sr2_representations_v1 r WHERE r.organisation_id=v_org AND r.repository_id=p_repository_id COLLATE "C" AND r.snapshot_id=p_snapshot_id COLLATE "C" AND r.projection_schema_version=p_schema COLLATE "C"
   AND r.provider_id=p_provider COLLATE "C" AND r.model_id=p_model COLLATE "C" AND r.model_version=p_version COLLATE "C" AND r.dimension=p_dimension
   AND EXISTS(SELECT FROM snapshot)
  ORDER BY r.subject_id COLLATE "C",r.generated_at DESC,r.recorded_at DESC,r.representation_id COLLATE "C" ASC LIMIT 10001),
 latest AS MATERIALIZED (SELECT DISTINCT ON (r.subject_id COLLATE "C") r.* FROM compatible r WHERE (SELECT count(*) FROM compatible)<=10000
  ORDER BY r.subject_id COLLATE "C",r.generated_at DESC,r.recorded_at DESC,r.representation_id COLLATE "C" ASC),
 base_fault AS MATERIALIZED (SELECT CASE
  WHEN NOT EXISTS(SELECT FROM snapshot) THEN 'REVISION_UNAVAILABLE'
  WHEN EXISTS(SELECT FROM snapshot sn WHERE NOT (sn.organisation_id IS NOT NULL AND sn.repository_id IS NOT NULL AND sn.snapshot_id IS NOT NULL AND sn.revision_scheme IS NOT NULL AND sn.full_revision IS NOT NULL AND sn.manifest_schema_version IS NOT NULL AND sn.manifest_fingerprint IS NOT NULL AND sn.manifest_entry_count IS NOT NULL AND (((sn.revision_scheme='GIT_SHA1_V1' AND sn.full_revision ~ '^[0-9a-f]{40}$' AND sn.full_revision<>repeat('0',40)) OR (sn.revision_scheme='GIT_SHA256_V1' AND sn.full_revision ~ '^[0-9a-f]{64}$' AND sn.full_revision<>repeat('0',64))) IS TRUE) AND ((sn.manifest_schema_version='GOVIA_SOURCE_MANIFEST_V1' AND sn.manifest_fingerprint ~ '^[0-9a-f]{64}$' AND sn.manifest_entry_count>=0) IS TRUE) AND ((sn.snapshot_id=pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(gov_repo.frame_identity(ARRAY['GOVIA_SR2_SNAPSHOT_V1',sn.organisation_id::text,sn.repository_id::text,sn.revision_scheme::text,sn.full_revision::text,sn.manifest_fingerprint::text]::text[]), 'UTF8')), 'hex')) IS TRUE))) OR NOT EXISTS(
   SELECT FROM gov_repo.sr2_captures_v1 c CROSS JOIN root rt CROSS JOIN snapshot sn WHERE c.organisation_id=v_org AND c.repository_id=p_repository_id COLLATE "C" AND c.snapshot_id=p_snapshot_id COLLATE "C"
    AND (c.organisation_id IS NOT NULL AND c.repository_id IS NOT NULL AND c.snapshot_id IS NOT NULL AND c.capture_id IS NOT NULL AND c.method_code IS NOT NULL AND c.method_version IS NOT NULL AND c.observed_provider_instance_id IS NOT NULL AND c.observed_provider_repository_id IS NOT NULL AND c.resolved_revision_scheme IS NOT NULL AND c.resolved_full_revision IS NOT NULL AND c.observed_manifest_fingerprint IS NOT NULL AND c.observed_at IS NOT NULL AND c.captured_at IS NOT NULL AND c.recorded_at IS NOT NULL AND ((c.method_code='CAPTURE_AT_IMMUTABLE_REVISION_V1' AND (octet_length(c.method_version) BETWEEN 1 AND 512 AND c.method_version ~ '[^[:space:]]' AND lower(btrim(c.method_version)) NOT IN ('latest','default','unknown')) AND octet_length(c.observed_provider_instance_id) BETWEEN 1 AND 512 AND c.observed_provider_instance_id ~ '[^[:space:]]' AND octet_length(c.observed_provider_repository_id) BETWEEN 1 AND 512 AND c.observed_provider_repository_id ~ '[^[:space:]]' AND octet_length(c.resolved_revision_scheme) BETWEEN 1 AND 512 AND c.resolved_revision_scheme ~ '[^[:space:]]' AND octet_length(c.resolved_full_revision) BETWEEN 1 AND 512 AND c.resolved_full_revision ~ '[^[:space:]]' AND c.observed_manifest_fingerprint ~ '^[0-9a-f]{64}$') IS TRUE) AND ((isfinite(c.observed_at) AND isfinite(c.captured_at) AND isfinite(c.recorded_at) AND c.observed_at<=c.captured_at AND c.captured_at<=c.recorded_at) IS TRUE)) AND c.observed_at BETWEEN '0001-01-01 UTC'::timestamptz AND (SELECT at FROM acquired_clock) AND c.captured_at BETWEEN '0001-01-01 UTC'::timestamptz AND (SELECT at FROM acquired_clock) AND c.recorded_at BETWEEN '0001-01-01 UTC'::timestamptz AND (SELECT at FROM acquired_clock) AND c.observed_provider_instance_id=rt.provider_instance_id
    AND c.observed_provider_repository_id=rt.provider_repository_id AND c.resolved_revision_scheme=sn.revision_scheme
    AND c.resolved_full_revision=sn.full_revision AND c.observed_manifest_fingerprint=sn.manifest_fingerprint) THEN 'CAPTURE_INCOMPLETE'
  WHEN (SELECT count(*) FROM compatible)>10000 THEN 'SCAN_BOUND'
  WHEN NOT EXISTS(SELECT FROM compatible) THEN 'NO_COMPATIBLE_REPRESENTATIONS'
  WHEN EXISTS(SELECT FROM compatible WHERE NOT valid_rep)
   OR EXISTS(SELECT FROM compatible GROUP BY representation_id HAVING count(*)>1) THEN 'INVALID_SOURCE_SUPPORT' END AS reason),

 -- Current authorization is evaluated without graph/document construction. Latest
 -- in-space identity is already frozen; exclusion cannot reveal an older version.
 disclosure AS MATERIALIZED (SELECT d.* FROM gov_repo.sr2_disclosure_profile_heads_v1 dh
  JOIN gov_repo.sr2_disclosure_profiles_v1 d ON d.organisation_id=dh.organisation_id AND d.repository_id=dh.repository_id
   AND d.purpose_code=dh.purpose_code AND d.disclosure_profile_id=dh.disclosure_profile_id AND d.disclosure_profile_version=dh.disclosure_profile_version
  WHERE dh.organisation_id=v_org AND dh.repository_id=p_repository_id COLLATE "C" AND dh.purpose_code='TECHNICAL_CONTEXT_HYDRATION_V1'
   AND dh.enabled AND (d.organisation_id=v_org AND d.repository_id=p_repository_id COLLATE "C" AND d.purpose_code='TECHNICAL_CONTEXT_HYDRATION_V1'
 AND gov_repo.sr2_list_valid_v1(ARRAY[d.disclosure_profile_id,d.disclosure_profile_version,d.admission_recipe_id,d.admission_recipe_version,d.policy_profile_id,d.policy_profile_version,d.handling_recipe_id,d.handling_recipe_version,d.required_projection_schema_version],9)
 AND NOT EXISTS(SELECT FROM unnest(ARRAY[d.disclosure_profile_id,d.disclosure_profile_version,d.admission_recipe_id,d.admission_recipe_version,d.policy_profile_id,d.policy_profile_version,d.handling_recipe_id,d.handling_recipe_version,d.required_projection_schema_version]) v WHERE lower(btrim(v)) IN ('latest','default','unknown'))
 AND d.document_recipe='GOVIA_TECHNICAL_CONTEXT_V1' AND d.recorded_at BETWEEN '0001-01-01 UTC'::timestamptz AND (SELECT at FROM acquired_clock)
 AND d.profile_fingerprint=encode(sha256(convert_to(gov_repo.frame_identity(ARRAY['GOVIA_SR2_DISCLOSURE_PROFILE_V1',d.organisation_id::text,d.repository_id,d.purpose_code,d.disclosure_profile_id,d.disclosure_profile_version,d.admission_recipe_id,d.admission_recipe_version,d.policy_profile_id,d.policy_profile_version,d.handling_recipe_id,d.handling_recipe_version,d.required_projection_schema_version,d.document_recipe]::text[]),'UTF8')),'hex')) IS TRUE),
 -- OFFSET 0 preserves parameterized unique-key lookups at every candidate
 -- count, including immediately after bulk ingestion with stale table statistics.
 -- These lookups admit current heads/recipes only; graph faults remain selected-hit faults.
 -- Validate each current entry head/admission against the materialized
 -- disclosure once. Candidate/source edges below perform only hashed membership.
 current_entry_eligibility AS MATERIALIZED (
  SELECT ch.entry_id,cu.admission_basis_fingerprint,(ch.enabled AND ch.head_revision>=1 AND ((cu.organisation_id IS NOT NULL AND cu.repository_id IS NOT NULL AND cu.snapshot_id IS NOT NULL AND cu.entry_id IS NOT NULL AND cu.source_fingerprint IS NOT NULL AND cu.entry_kind IS NOT NULL AND cu.byte_length IS NOT NULL AND cu.encoding_id IS NOT NULL AND cu.line_count IS NOT NULL AND cu.source_admission_id IS NOT NULL AND cu.evaluation_id IS NOT NULL AND cu.capture_id IS NOT NULL AND cu.capture_observed_at IS NOT NULL AND cu.admission_recipe_id IS NOT NULL AND cu.admission_recipe_version IS NOT NULL AND cu.policy_profile_id IS NOT NULL AND cu.policy_profile_version IS NOT NULL AND cu.outcome IS NOT NULL AND cu.reason_code IS NOT NULL AND cu.protected_eligible IS NOT NULL AND cu.admission_basis_fingerprint IS NOT NULL AND cu.evaluated_at IS NOT NULL AND cu.recorded_at IS NOT NULL AND (((octet_length(cu.admission_recipe_id) BETWEEN 1 AND 512 AND cu.admission_recipe_id ~ '[^[:space:]]' AND lower(btrim(cu.admission_recipe_id)) NOT IN ('latest','default','unknown')) AND (octet_length(cu.admission_recipe_version) BETWEEN 1 AND 512 AND cu.admission_recipe_version ~ '[^[:space:]]' AND lower(btrim(cu.admission_recipe_version)) NOT IN ('latest','default','unknown')) AND (octet_length(cu.policy_profile_id) BETWEEN 1 AND 512 AND cu.policy_profile_id ~ '[^[:space:]]' AND lower(btrim(cu.policy_profile_id)) NOT IN ('latest','default','unknown')) AND (octet_length(cu.policy_profile_version) BETWEEN 1 AND 512 AND cu.policy_profile_version ~ '[^[:space:]]' AND lower(btrim(cu.policy_profile_version)) NOT IN ('latest','default','unknown'))) IS TRUE) AND (((cu.outcome='PROTECTED_ELIGIBLE' AND cu.content_class IS NOT NULL AND cu.content_class='PROTECTED_CONTEXT_V1' AND cu.protected_eligible AND cu.reason_code='NONE' AND cu.entry_kind='REGULAR_FILE' AND cu.encoding_id='UTF8_STRICT_V1' AND cu.byte_length<=524288) OR (cu.outcome='METADATA_ONLY' AND cu.content_class IS NOT NULL AND cu.content_class='METADATA_ONLY_V1' AND NOT cu.protected_eligible AND cu.reason_code IN ('POLICY_WITHHELD','SECRET_SENSITIVE','UNSUPPORTED_ENCODING','BINARY','GENERATED','MINIFIED','LICENSE_RESTRICTED','EGRESS_RESTRICTED','OVERSIZED','UNQUALIFIED','SYMLINK','SUBMODULE')) OR (cu.outcome='REJECTED' AND cu.content_class IS NULL AND NOT cu.protected_eligible AND cu.reason_code IN ('POLICY_WITHHELD','SECRET_SENSITIVE','UNSUPPORTED_ENCODING','BINARY','GENERATED','MINIFIED','LICENSE_RESTRICTED','EGRESS_RESTRICTED','OVERSIZED','UNQUALIFIED','SYMLINK','SUBMODULE'))) IS TRUE) AND ((cu.admission_basis_fingerprint=pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(gov_repo.frame_identity(ARRAY['GOVIA_SR2_ADMISSION_BASIS_V1']::text[] || (ARRAY[cu.organisation_id::text,cu.repository_id::text,cu.snapshot_id::text,cu.entry_id::text,cu.admission_recipe_id::text,cu.admission_recipe_version::text,cu.policy_profile_id::text,cu.policy_profile_version::text,cu.outcome::text]::text[] || ARRAY[CASE WHEN cu.content_class IS NULL THEN '0' ELSE '1' END,coalesce(cu.content_class::text,'')]::text[] || ARRAY[cu.reason_code,CASE WHEN cu.protected_eligible THEN '1' ELSE '0' END])), 'UTF8')), 'hex')) IS TRUE) AND ((cu.source_admission_id=pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(gov_repo.frame_identity(ARRAY['GOVIA_SR2_SOURCE_ADMISSION_V1',cu.organisation_id::text,cu.repository_id::text,cu.snapshot_id::text,cu.entry_id::text,cu.evaluation_id::text,cu.admission_basis_fingerprint::text]::text[]), 'UTF8')), 'hex')) IS TRUE) AND ((isfinite(cu.capture_observed_at) AND isfinite(cu.evaluated_at) AND isfinite(cu.recorded_at) AND cu.capture_observed_at<=cu.evaluated_at AND cu.evaluated_at<=cu.recorded_at) IS TRUE)) AND cu.capture_observed_at BETWEEN '0001-01-01 UTC'::timestamptz AND (SELECT at FROM acquired_clock) AND cu.evaluated_at BETWEEN '0001-01-01 UTC'::timestamptz AND (SELECT at FROM acquired_clock) AND cu.recorded_at BETWEEN '0001-01-01 UTC'::timestamptz AND (SELECT at FROM acquired_clock)) AND cu.outcome='PROTECTED_ELIGIBLE' AND cu.content_class='PROTECTED_CONTEXT_V1'
    AND cu.protected_eligible AND cu.reason_code='NONE' AND cu.admission_recipe_id=d.admission_recipe_id
    AND cu.admission_recipe_version=d.admission_recipe_version AND cu.policy_profile_id=d.policy_profile_id AND cu.policy_profile_version=d.policy_profile_version) IS TRUE AS eligible
  FROM gov_repo.sr2_source_admission_heads_v1 ch CROSS JOIN disclosure d
  LEFT JOIN gov_repo.sr2_source_admissions_v1 cu ON cu.organisation_id=v_org AND cu.repository_id=p_repository_id COLLATE "C"
   AND cu.snapshot_id=p_snapshot_id COLLATE "C" AND cu.entry_id=ch.entry_id AND cu.source_admission_id=ch.source_admission_id
  WHERE ch.organisation_id=v_org AND ch.repository_id=p_repository_id COLLATE "C" AND ch.snapshot_id=p_snapshot_id COLLATE "C"
   AND ch.purpose_code='TECHNICAL_CONTEXT_HYDRATION_V1'),
 eligible AS MATERIALIZED (SELECT r.*,s.subject_family FROM latest r
  LEFT JOIN LATERAL (SELECT s.* FROM gov_repo.sr2_subjects_v1 s
   WHERE s.organisation_id=v_org AND s.repository_id=p_repository_id COLLATE "C" AND s.snapshot_id=p_snapshot_id COLLATE "C"
    AND s.subject_id=r.subject_id OFFSET 0) s ON true
  LEFT JOIN LATERAL (SELECT p.* FROM gov_repo.sr2_projections_v1 p
   WHERE p.organisation_id=v_org AND p.repository_id=p_repository_id COLLATE "C" AND p.snapshot_id=p_snapshot_id COLLATE "C"
    AND p.subject_id=r.subject_id AND p.projection_id=r.projection_id OFFSET 0) p ON true
  CROSS JOIN disclosure d WHERE (p.projection_id IS NULL OR (p.projection_schema_version=d.required_projection_schema_version AND p.document_recipe=d.document_recipe
   AND p.handling_recipe_id=d.handling_recipe_id AND p.handling_recipe_version=d.handling_recipe_version))
  AND NOT EXISTS(SELECT FROM LATERAL (SELECT ps.* FROM gov_repo.sr2_projection_sources_v1 ps
   WHERE ps.organisation_id=v_org AND ps.repository_id=p_repository_id COLLATE "C" AND ps.snapshot_id=p_snapshot_id COLLATE "C"
    AND ps.subject_id=r.subject_id AND ps.projection_id=r.projection_id OFFSET 0) ps
   WHERE ((ps.entry_id,ps.admission_basis_fingerprint) IN (
    SELECT entry_id,admission_basis_fingerprint FROM current_entry_eligibility WHERE eligible)) IS NOT TRUE)),
 scoreable AS MATERIALIZED (SELECT * FROM eligible WHERE (SELECT reason FROM base_fault) IS NULL),
 scored AS MATERIALIZED (SELECT r.*,1-(__vector__.l2_normalize(r.embedding) OPERATOR(__vector__.<=>) v_query_unit) AS relevance FROM scoreable r),
 numeric_invariant AS MATERIALIZED (SELECT coalesce(bool_or((relevance BETWEEN -1 AND 1) IS NOT TRUE),false) AS invalid FROM scored),
 ranked AS MATERIALIZED (SELECT *,row_number() OVER(ORDER BY relevance DESC,subject_family COLLATE "C",subject_id COLLATE "C",representation_id COLLATE "C") AS rank
  FROM scored WHERE NOT (SELECT invalid FROM numeric_invariant) AND relevance>=p_threshold ORDER BY relevance DESC,subject_family COLLATE "C",subject_id COLLATE "C",representation_id COLLATE "C" LIMIT p_limit),
 graphs AS MATERIALIZED (
  SELECT r.*,g.* FROM ranked r CROSS JOIN root rt CROSS JOIN snapshot sn
  LEFT JOIN LATERAL (SELECT s.* FROM gov_repo.sr2_subjects_v1 s WHERE s.organisation_id=v_org AND s.repository_id=p_repository_id COLLATE "C" AND s.snapshot_id=p_snapshot_id COLLATE "C" AND s.subject_id=r.subject_id OFFSET 0) s ON true
  LEFT JOIN LATERAL (SELECT p.* FROM gov_repo.sr2_projections_v1 p WHERE p.organisation_id=v_org AND p.repository_id=p_repository_id COLLATE "C" AND p.snapshot_id=p_snapshot_id COLLATE "C" AND p.subject_id=r.subject_id AND p.projection_id=r.projection_id OFFSET 0) p ON true
  LEFT JOIN LATERAL (SELECT b.* FROM gov_repo.sr2_protected_projections_v1 b WHERE b.organisation_id=v_org AND b.repository_id=p_repository_id COLLATE "C" AND b.snapshot_id=p_snapshot_id COLLATE "C" AND b.subject_id=r.subject_id AND b.projection_id=r.projection_id OFFSET 0) b ON true
  LEFT JOIN LATERAL (SELECT hit_entry.* FROM gov_repo.sr2_manifest_entries_v1 hit_entry WHERE hit_entry.organisation_id=v_org AND hit_entry.repository_id=p_repository_id COLLATE "C" AND hit_entry.snapshot_id=p_snapshot_id COLLATE "C" AND hit_entry.entry_id=s.entry_id OFFSET 0) hit_entry ON true
  LEFT JOIN LATERAL (SELECT cl.* FROM gov_repo.sr2_chunk_locators_v1 cl WHERE cl.organisation_id=v_org AND cl.repository_id=p_repository_id COLLATE "C" AND cl.snapshot_id=p_snapshot_id COLLATE "C" AND cl.locator_id=s.chunk_locator_id OFFSET 0) cl ON true
  LEFT JOIN LATERAL (SELECT sy.* FROM gov_repo.sr2_symbol_locators_v1 sy WHERE sy.organisation_id=v_org AND sy.repository_id=p_repository_id COLLATE "C" AND sy.snapshot_id=p_snapshot_id COLLATE "C" AND sy.locator_id=s.symbol_locator_id OFFSET 0) sy ON true
  LEFT JOIN gov_repo.sr2_disclosure_profile_heads_v1 dh ON dh.organisation_id=v_org AND dh.repository_id=p_repository_id COLLATE "C" AND dh.purpose_code='TECHNICAL_CONTEXT_HYDRATION_V1'
  LEFT JOIN gov_repo.sr2_disclosure_profiles_v1 d ON d.organisation_id=v_org AND d.repository_id=p_repository_id COLLATE "C"
   AND d.purpose_code=dh.purpose_code AND d.disclosure_profile_id=dh.disclosure_profile_id AND d.disclosure_profile_version=dh.disclosure_profile_version
  CROSS JOIN LATERAL (
 WITH items AS MATERIALIZED (SELECT i.facet_kind,i.item_key,i.grounding_set_id,i.scope_kind,i.anchor_subject_id,i.method_code,i.payload_fingerprint,
