 capture_rows AS MATERIALIZED (SELECT cr.id AS expected_id,c.*,jsonb_build_object('capture_id',c.capture_id,'method',jsonb_build_object('code',c.method_code,'version',c.method_version),'observed_at',CASE WHEN isfinite(c.observed_at) THEN to_char(c.observed_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') ELSE NULL END,'captured_at',CASE WHEN isfinite(c.captured_at) THEN to_char(c.captured_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') ELSE NULL END,'recorded_at',CASE WHEN isfinite(c.recorded_at) THEN to_char(c.recorded_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') ELSE NULL END) AS dto,
  ((c.organisation_id IS NOT NULL AND c.repository_id IS NOT NULL AND c.snapshot_id IS NOT NULL AND c.capture_id IS NOT NULL AND c.method_code IS NOT NULL AND c.method_version IS NOT NULL AND c.observed_provider_instance_id IS NOT NULL AND c.observed_provider_repository_id IS NOT NULL AND c.resolved_revision_scheme IS NOT NULL AND c.resolved_full_revision IS NOT NULL AND c.observed_manifest_fingerprint IS NOT NULL AND c.observed_at IS NOT NULL AND c.captured_at IS NOT NULL AND c.recorded_at IS NOT NULL AND ((c.method_code='CAPTURE_AT_IMMUTABLE_REVISION_V1' AND (octet_length(c.method_version) BETWEEN 1 AND 512 AND c.method_version ~ '[^[:space:]]' AND lower(btrim(c.method_version)) NOT IN ('latest','default','unknown')) AND octet_length(c.observed_provider_instance_id) BETWEEN 1 AND 512 AND c.observed_provider_instance_id ~ '[^[:space:]]' AND octet_length(c.observed_provider_repository_id) BETWEEN 1 AND 512 AND c.observed_provider_repository_id ~ '[^[:space:]]' AND octet_length(c.resolved_revision_scheme) BETWEEN 1 AND 512 AND c.resolved_revision_scheme ~ '[^[:space:]]' AND octet_length(c.resolved_full_revision) BETWEEN 1 AND 512 AND c.resolved_full_revision ~ '[^[:space:]]' AND c.observed_manifest_fingerprint ~ '^[0-9a-f]{64}$') IS TRUE) AND ((isfinite(c.observed_at) AND isfinite(c.captured_at) AND isfinite(c.recorded_at) AND c.observed_at<=c.captured_at AND c.captured_at<=c.recorded_at) IS TRUE)) AND c.observed_at BETWEEN '0001-01-01 UTC'::timestamptz AND (SELECT at FROM acquired_clock) AND c.captured_at BETWEEN '0001-01-01 UTC'::timestamptz AND (SELECT at FROM acquired_clock) AND c.recorded_at BETWEEN '0001-01-01 UTC'::timestamptz AND (SELECT at FROM acquired_clock) AND c.observed_provider_instance_id=rt.provider_instance_id
   AND c.observed_provider_repository_id=rt.provider_repository_id AND c.resolved_revision_scheme=sn.revision_scheme
