int',c.collection_fingerprint,'items',coalesce((SELECT jsonb_agg(dto ORDER BY item_key COLLATE "C") FROM (SELECT item_key,dto FROM items WHERE facet_kind=c.facet_kind) j),'[]'::jsonb)) FROM collections c WHERE c.facet_kind='ENTRYPOINT_DESCRIPTOR')))),'embedding_space',v_space,'representation_provenance',jsonb_build_object('capture_id',r.capture_id,'capture_observed_at',CASE WHEN isfinite(r.capture_observed_at) THEN to_char(r.capture_observed_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') ELSE NULL END,'generated_at',CASE WHEN isfinite(r.generated_at) THEN to_char(r.generated_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') ELSE NULL END,'indexed_at',CASE WHEN isfinite(r.indexed_at) THEN to_char(r.indexed_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') ELSE NULL END,'recorded_at',CASE WHEN isfinite(r.recorded_at) THEN to_char(r.recorded_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') ELSE NULL END),'disclosure',jsonb_build_object('purpose',d.purpose_code,'profile_id',d.disclosure_profile_id,'profile_version',d.disclosure_profile_version,'profile_fingerprint',d.profile_fingerprint,'profile_recorded_at',CASE WHEN isfinite(d.recorded_at) THEN to_char(d.recorded_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') ELSE NULL END,'profile_head_revision',dh.head_revision::text,'admission_recipe',jsonb_build_object('id',d.admission_recipe_id,'version',d.admission_recipe_version),'policy_profile',jsonb_build_object('id',d.policy_profile_id,'version',d.policy_profile_version),'handling_recipe',jsonb_build_object('id',d.handling_recipe_id,'version',d.handling_recipe_version),'required_projection_schema_version',d.required_projection_schema_version,'document_recipe',d.document_recipe),'support',jsonb_build_object('source_subjects',coalesce((SELECT jsonb_agg(dto ORDER BY source_subject_id COLLATE "C") FROM (SELECT source_subject_id,subject_dto AS dto FROM primary_members) j),'[]'::jsonb),'entries',coalesce((SELECT jsonb_agg(dto ORDER BY entry_id COLL